<script setup lang="ts">
import {ref,watch,onMounted,onBeforeUnmount,computed} from 'vue';
import {ApiError,unwrap,mutationHeaders,type components} from '../../api-client/src';
import {StaffSession,explainError} from './auth';
type S=components['schemas'];type Connection=S['IntegrationConnection'];type Mapping=S['IntegrationMapping'];type Event=S['IntegrationInventoryEvent'];type Preview=S['IntegrationStockPreview'];
const props=defineProps<{session:StaffSession}>();
const connections=ref<Connection[]>([]),mappings=ref<Mapping[]>([]),events=ref<Event[]>([]),applications=ref<S['IntegrationStockApplication'][]>([]),offers=ref<S['ManagedOffer'][]>([]);
const cursors=ref<Record<string,string|null>>({});const selected=ref(''),offerId=ref(''),label=ref('TEST_ONLY_STOCK'),externalSku=ref(''),warehouse=ref(''),scenario=ref(false),password=ref('');
const busy=ref(false),enabled=ref(false),error=ref(''),notice=ref(''),preview=ref<Preview>(),actual=ref<S['ManagedOffer']>();
const currentConnection=computed(()=>connections.value.find(c=>c.id===selected.value));const zeroOffers=computed(()=>offers.value.filter(o=>o.store_id===props.session.state.storeId&&o.inventory.on_hand_qty===0&&o.inventory.reserved_qty===0&&o.sale_status!=='DELISTED'));
const keys=new Map<string,string>();let generation=0;
function permissions(){return props.session.state.principal?.permissions.join(',')??'';}
function stamp(){const g=generation,session=props.session.state.principal?.session_id,store=props.session.state.storeId,perms=permissions();return()=>g===generation&&session===props.session.state.principal?.session_id&&store===props.session.state.storeId&&perms===permissions();}
function reset(){generation++;connections.value=[];mappings.value=[];events.value=[];applications.value=[];offers.value=[];cursors.value={};selected.value='';offerId.value='';externalSku.value='';warehouse.value='';label.value='TEST_ONLY_STOCK';scenario.value=false;password.value='';preview.value=undefined;actual.value=undefined;busy.value=false;enabled.value=false;error.value='';notice.value='';keys.clear();}
const evidence=()=>[{kind:'TEST_SCENARIO' as const,reference:'TEST_ONLY_MERCHANT_STOCK_UI'}];
function report(e:unknown){if(e instanceof ApiError&&e.code==='ERP_WMS_SIMULATION_DISABLED'){enabled.value=false;error.value='';}else{error.value=e instanceof ApiError&&e.code==='INTEGRATION_BOOTSTRAP_OPEN_RESPONSIBILITY'?'该报价仍有未结订单、售后或退款责任，暂不能接入库存演练。':explainError(e);if(e instanceof ApiError&&e.status===409)preview.value=undefined;}}
async function readConnections(more=false){const valid=stamp(),store=props.session.state.storeId;if(!store||!props.session.can('integration.read'))return;const r=unwrap(await props.session.client.api.GET('/merchant/stores/{store_id}/integration-connections',{params:{path:{store_id:store},query:{limit:50,...more&&cursors.value.connections?{cursor:cursors.value.connections}:{}}}}));if(!valid())return;connections.value=more?[...connections.value,...r.data]:r.data;cursors.value.connections=r.page.next_cursor;enabled.value=true;if(!connections.value.some(c=>c.id===selected.value))selected.value=connections.value[0]?.id??'';}
async function readPart(kind:'mappings'|'events'|'applications',more=false){const valid=stamp(),connection_id=selected.value,store_id=props.session.state.storeId;if(!connection_id)return;const params={path:{store_id,connection_id},query:{limit:50,...more&&cursors.value[kind]?{cursor:cursors.value[kind]!}:{}}};
 if(kind==='mappings'){const r=unwrap(await props.session.client.api.GET('/merchant/stores/{store_id}/integration-connections/{connection_id}/mappings',{params}));if(valid()&&selected.value===connection_id){mappings.value=more?[...mappings.value,...r.data]:r.data;cursors.value.mappings=r.page.next_cursor;}}
 else if(kind==='events'){const r=unwrap(await props.session.client.api.GET('/merchant/stores/{store_id}/integration-connections/{connection_id}/inventory-events',{params}));if(valid()&&selected.value===connection_id){events.value=more?[...events.value,...r.data]:r.data;cursors.value.events=r.page.next_cursor;}}
 else{const r=unwrap(await props.session.client.api.GET('/merchant/stores/{store_id}/integration-connections/{connection_id}/inventory-applications',{params}));if(valid()&&selected.value===connection_id){applications.value=more?[...applications.value,...r.data]:r.data;cursors.value.applications=r.page.next_cursor;}}
}
async function readOffers(){if(!props.session.can('offer.read'))return;const valid=stamp(),rows:S['ManagedOffer'][]=[];let cursor:string|null=null;do{const r:S['ManagedOfferListEnvelope']=unwrap(await props.session.client.api.GET('/merchant/offers',{params:{query:{limit:100,store_id:props.session.state.storeId,...cursor?{cursor}:{}}}}));if(!valid())return;rows.push(...r.data);cursor=r.page.next_cursor;}while(cursor);if(valid())offers.value=rows;}
async function details(){mappings.value=[];events.value=[];applications.value=[];preview.value=undefined;actual.value=undefined;await Promise.all([readPart('mappings'),readPart('events'),readPart('applications')]);}
async function load(){if(busy.value)return;const valid=stamp();busy.value=true;error.value='';try{await readConnections();if(valid()&&enabled.value)await Promise.all([details(),readOffers()]);}catch(e){if(valid())report(e);}finally{if(valid())busy.value=false;}}
async function choose(){if(busy.value)return;const valid=stamp();busy.value=true;error.value='';try{await details();}catch(e){if(valid())report(e);}finally{if(valid())busy.value=false;}}
async function more(kind:'connections'|'mappings'|'events'|'applications'){if(busy.value)return;const valid=stamp();busy.value=true;try{await(kind==='connections'?readConnections(true):readPart(kind,true));}catch(e){if(valid())report(e);}finally{if(valid())busy.value=false;}}
async function verified(action:'integration.manage'|'integration.mapping.write'|'integration.stock.apply',work:(proof:string)=>Promise<unknown>){const valid=stamp();const p=await props.session.client.reverify({action,password:password.value});if(!valid())throw new ApiError(401,'SESSION_CHANGED','');return work(p.reverify_token);}
async function command(fingerprint:string,work:(key:string)=>Promise<unknown>){if(busy.value)return;const valid=stamp(),key=keys.get(fingerprint)??crypto.randomUUID();keys.set(fingerprint,key);busy.value=true;error.value='';notice.value='';try{await work(key);if(!valid())return;keys.delete(fingerprint);password.value='';preview.value=undefined;notice.value='合成记录已保存，已重新读取持久化记录。';await readConnections();if(valid())await Promise.all([readPart('mappings'),readPart('events'),readPart('applications'),readOffers()]);}catch(e){if(valid())report(e);}finally{if(valid())busy.value=false;}}
async function create(){const valid=stamp();if(!scenario.value){error.value='请确认仅用于合成演练。';return;}const store_id=props.session.state.storeId,body:S['IntegrationConnectionInput']={label:label.value,mode:'SIMULATED_TEST',inventory_basis:'DEDICATED_REMAINING_AFTER_WATERMARK',evidence_refs:evidence()};await command(JSON.stringify(['create',store_id,body]),key=>verified('integration.manage',async proof=>{const r=unwrap(await props.session.client.api.POST('/merchant/stores/{store_id}/integration-connections',{params:{path:{store_id},header:mutationHeaders(key,proof)},body}));if(valid())selected.value=r.data.id;return r;}));}
async function state(c:Connection){const body:S['IntegrationConnectionStateInput']=c.state==='ACTIVE'?{state:'PAUSED',reason_code:'OPERATOR_PAUSE'}:{state:'ACTIVE',reason_code:'TEST_SCENARIO_START'};await command(JSON.stringify(['state',c.id,c.version,body]),key=>verified('integration.manage',async proof=>unwrap(await props.session.client.api.PUT('/merchant/stores/{store_id}/integration-connections/{connection_id}/state',{params:{path:{store_id:props.session.state.storeId,connection_id:c.id},header:mutationHeaders(key,proof,c.version)},body}))));}
async function bind(){const c=currentConnection.value;if(!c||!scenario.value||!zeroOffers.value.some(o=>o.id===offerId.value)){error.value='请选择本店空库存报价并确认合成演练。';return;}const body:S['IntegrationMappingInput']={offer_id:offerId.value,external_sku:externalSku.value,external_warehouse:warehouse.value,unit:'PIECE',evidence_refs:evidence()};await command(JSON.stringify(['bind',c.id,c.version,body]),key=>verified('integration.mapping.write',async proof=>unwrap(await props.session.client.api.POST('/merchant/stores/{store_id}/integration-connections/{connection_id}/mappings',{params:{path:{store_id:props.session.state.storeId,connection_id:c.id},header:mutationHeaders(key,proof,c.version)},body}))));}
async function retire(m:Mapping){await command(JSON.stringify(['retire',m.id,m.version]),key=>verified('integration.mapping.write',async proof=>unwrap(await props.session.client.api.PUT('/merchant/stores/{store_id}/integration-connections/{connection_id}/mappings/{mapping_id}/state',{params:{path:{store_id:props.session.state.storeId,connection_id:selected.value,mapping_id:m.id},header:mutationHeaders(key,proof,m.version)},body:{state:'RETIRED',reason_code:'TEST_SCENARIO_RETIRED'}}))));}
async function assess(e:Event){if(busy.value)return;const valid=stamp(),connection_id=selected.value,tag='preview:'+e.id,key=keys.get(tag)??crypto.randomUUID();keys.set(tag,key);busy.value=true;error.value='';preview.value=undefined;try{const r=unwrap(await props.session.client.api.POST('/merchant/stores/{store_id}/integration-connections/{connection_id}/inventory-events/{event_id}/previews',{params:{path:{store_id:props.session.state.storeId,connection_id,event_id:e.id},header:mutationHeaders(key)},body:{}}));if(valid()&&connection_id===selected.value){preview.value=r.data;keys.delete(tag);}}catch(e){if(valid())report(e);}finally{if(valid())busy.value=false;}}
async function apply(){const snap=preview.value,valid=stamp();if(!snap?.eligible)return;if(Date.parse(snap.expires_at)<=Date.now()){preview.value=undefined;error.value='库存预览已过期，请重新生成后确认。';return;}await command(JSON.stringify(['apply',snap.id,snap.snapshot_sha256]),key=>verified('integration.stock.apply',async proof=>{const app=unwrap(await props.session.client.api.POST('/merchant/stores/{store_id}/integration-connections/{connection_id}/inventory-previews/{preview_id}/apply',{params:{path:{store_id:props.session.state.storeId,connection_id:selected.value,preview_id:snap.id},header:mutationHeaders(key,proof)},body:{accepted_snapshot_sha256:snap.snapshot_sha256}}));const stock=unwrap(await props.session.client.api.GET('/merchant/offers/{id}',{params:{path:{id:app.data.offer_id}}}));if(valid())actual.value=stock.data;return app;}));}
watch(()=>[props.session.state.principal?.session_id,props.session.state.storeId,permissions()],()=>{reset();void load();});onMounted(()=>{void load();});onBeforeUnmount(reset);
</script>
<template>
 <section aria-label="合成库存对账">
<h2>库存对账演练</h2><p>仅用于合成系统演练，真实 ERP/WMS 尚未接入。库存与确认水位由服务器读取。创建连接或映射不会增加库存。</p>
 <p v-if="!enabled&&!error" role="status">{{ busy?'正在读取库存演练配置…':'当前环境未开启库存对账演练。' }}</p><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
 <button :disabled="busy" @click="load">刷新库存对账</button>
 <template v-if="enabled">
<label v-if="session.can('integration.manage')||session.can('integration.mapping.write')||session.can('integration.stock.apply')">操作验证密码<input v-model="password" type="password" autocomplete="off" /></label>
 <label v-if="session.can('integration.manage')||session.can('integration.mapping.write')"><input v-model="scenario" type="checkbox" />我确认仅用于合成演练</label>
 <form v-if="session.can('integration.manage')" @submit.prevent="create"><fieldset :disabled="busy"><legend>创建暂停的合成连接</legend><label>连接标签<input v-model="label" required pattern="TEST_ONLY_[A-Za-z0-9_.:-]{1,100}" maxlength="110" /></label><button>创建合成连接</button></fieldset></form>
 <label v-if="connections.length">选择合成连接<select v-model="selected" aria-label="选择合成连接" :disabled="busy" @change="choose"><option v-for="c in connections" :key="c.id" :value="c.id">{{ c.label }} · {{ c.state==='ACTIVE'?'已启用':'已暂停' }}</option></select></label><button v-if="cursors.connections" :disabled="busy" @click="more('connections')">更多连接</button>
 <template v-if="currentConnection">
<p>连接 {{ currentConnection.id }} · 版本 {{ currentConnection.version }}</p><button v-if="session.can('integration.manage')" :disabled="busy" @click="state(currentConnection)">{{ currentConnection.state==='ACTIVE'?'暂停合成连接':'启用合成连接' }}</button>
 <form v-if="currentConnection.state==='PAUSED'&&session.can('integration.mapping.write')" @submit.prevent="bind"><fieldset :disabled="busy"><legend>映射本店空库存报价</legend><p>只允许实物和预占均为零、没有旧未结订单、售后或退款责任的专用演练报价。</p><label>空库存报价<select v-model="offerId" aria-label="空库存报价" required><option value="">请选择</option><option v-for="o in zeroOffers" :key="o.id" :value="o.id">{{ o.sku_code }} · {{ o.id }}</option></select></label><label>合成外部 SKU<input v-model="externalSku" required pattern="TEST_ONLY_[A-Za-z0-9_.:-]{1,100}" maxlength="110" /></label><label>合成仓库<input v-model="warehouse" required pattern="TEST_ONLY_[A-Za-z0-9_.:-]{1,100}" maxlength="110" /></label><p>库存单位：件</p><button>保存合成映射</button></fieldset></form>
 <h3>映射记录</h3><ul><li v-for="m in mappings" :key="m.id">{{ m.external_sku }} · {{ m.external_warehouse }} · {{ m.state==='ACTIVE'?'使用中':'已退役' }} <button v-if="m.state==='ACTIVE'&&session.can('integration.mapping.write')" :disabled="busy" @click="retire(m)">退役映射 {{ m.external_sku }}</button></li></ul><button v-if="cursors.mappings" :disabled="busy" @click="more('mappings')">更多映射</button>
 <h3>服务器库存事件</h3><p v-if="!events.length">暂无服务器库存事件。请先配置映射并启用合成连接。</p><article v-for="e in events" :key="e.id"><p>{{ e.external_event_id }} · 外部版本 {{ e.external_version }} · 专用剩余 {{ e.external_remaining_qty }} · 已确认本地序列 {{ e.acknowledged_local_sequence }}</p><button v-if="session.can('integration.stock.assess')" :disabled="busy" @click="assess(e)">生成库存预览 {{ e.external_event_id }}</button></article><button v-if="cursors.events" :disabled="busy" @click="more('events')">更多库存事件</button>
 <article v-if="preview" aria-label="库存应用预览"><h3>五分钟库存预览</h3><p>当前实物 {{ preview.on_hand_qty }} · 已预占 {{ preview.reserved_qty }} · 目标实物 {{ preview.target_on_hand_qty===null?'不可用':preview.target_on_hand_qty }} · 差额 {{ preview.delta_qty===null?'不可用':preview.delta_qty }}</p><p>有效至 {{ new Date(preview.expires_at).toLocaleString() }}</p><p v-if="!preview.eligible" role="status">当前不可应用：{{ preview.blocked_reasons.join('、') }}</p><button v-if="session.can('integration.stock.apply')" :disabled="busy||!preview.eligible||Date.parse(preview.expires_at)<=Date.now()" @click="apply">确认应用本次库存预览</button></article>
 <h3>持久化应用记录</h3><ul><li v-for="a in applications" :key="a.id">应用 {{ a.id }} · 实物 {{ a.before_on_hand_qty }} → {{ a.resulting_on_hand_qty }} · 预占 {{ a.reserved_qty }} · 库存版本 {{ a.resulting_inventory_version }}</li></ul><button v-if="cursors.applications" :disabled="busy" @click="more('applications')">更多应用记录</button><p v-if="actual" role="status">原报价回读：实物 {{ actual.inventory.on_hand_qty }} · 预占 {{ actual.inventory.reserved_qty }} · 可用 {{ actual.inventory.available_qty }}</p>
 </template>
</template>
</section>
</template>
